/**
 * PasscodeGate.js — A simple passcode wall shown before the dashboard loads.
 *
 * This exists because the dashboard currently only has training/placeholder
 * data behind it (see the on-screen warning below) and isn't ready for
 * general viewing yet. Wrapping <App> in this component in index.js means
 * nothing in App.js — including its data fetch — runs until the passcode
 * has been entered correctly.
 *
 * IMPORTANT — this is NOT real security. React/CRA ships the entire
 * PASSCODE constant below in plain text inside the built JS bundle, so
 * anyone who opens browser dev tools can read it directly out of the
 * source. It only stops casual/accidental visits, e.g. someone finding the
 * link before it's ready to share. Don't use this pattern to protect
 * anything that actually needs to stay private.
 */
import React, { useState } from "react";

// ─── Change this to set/update the preview passcode ───────────────────────────
const PASSCODE = "phiuk";
// NOTE: the passcode is intentionally asked for on every visit — nothing is
// remembered across page loads or sessions (no localStorage/sessionStorage
// involved). If you'd rather unlock once and stay unlocked, that's a
// straightforward re-add — just ask.

// Same design tokens as App.js, kept local so this gate renders identically
// whether or not the rest of the app has loaded yet. Blues are from the
// SimPaths logo; #6095DA is too light for text, so text is navy.
const HEAD_BG   = "#f4f8fd";   // header background (pale SimPaths blue)
const HEAD_LINE = "#d4e2f3";
const INK       = "#1d2d41";   // headings and text on the blues (13:1 on white)
const BLUE      = "#6095DA";   // SimPaths logo blue: borders, focus, accents
const CORAL     = "#ff5d51";   // button (white text at 19px bold = large text, 3:1)
const BORDER    = "#E1DFE5";
const TEXT_DARK = "#1e293b";
const TEXT_MID  = "#475569";
const WARN_TEXT = "#9a3412";   // warning text on WARN_BG (7:1)
const WARN_BG   = "#fff4f2";
const ERROR     = "#b42318";   // error message (6.5:1 on white)
const STRIPE    = "linear-gradient(90deg,#f0cc60 0%,#f0b454 14%,#f09054 28%,#fc6048 42%,#D23A5F 56%,#972A6C 70%,#7C36A6 84%,#6095DA 100%)";

/**
 * PasscodeGate — renders its `children` only after the correct passcode has
 * been entered THIS visit. Nothing is persisted, so reloading the page or
 * returning later always shows this gate again. Until unlocked, it renders
 * a standalone landing page carrying the "training data, illustrative only"
 * warning and a passcode form.
 *
 * @param {{ children: React.ReactNode }} props
 */
function PasscodeGate({ children }) {
  const [unlocked, setUnlocked] = useState(false);
  const [value, setValue] = useState("");
  const [error, setError] = useState(false);
  const [focused, setFocused] = useState(false);

  /** Checks the typed value against PASSCODE and unlocks (or shows an error) on submit. */
  const handleSubmit = (e) => {
    e.preventDefault();
    if (value.trim() === PASSCODE) {
      setUnlocked(true);
      setError(false);
    } else {
      setError(true);
    }
  };

  if (unlocked) return children;

  return (
    <div style={{ fontFamily: "Inter, system-ui, sans-serif", minHeight: "100vh", background: "#ffffff", color: TEXT_DARK, display: "flex", flexDirection: "column" }}>

      {/* Header — matches the dashboard's: pale blue bar, logo, title, gradient ribbon */}
      <header style={{ background: HEAD_BG }}>
        <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "10px clamp(16px, 4vw, 48px)", minHeight: 60, boxSizing: "border-box", flexWrap: "wrap" }}>
          <img src={`${process.env.PUBLIC_URL}/SimPaths-logo-transparent.png`} alt="SimPaths logo" style={{ height: 32, width: "auto", display: "block" }} />
          <p style={{ margin: 0, color: INK, fontSize: 18, lineHeight: 1.2, display: "flex", alignItems: "center", flexWrap: "wrap" }}>
            <span style={{ fontWeight: 700 }}>SimPaths</span>{" "}
            <span style={{ fontWeight: 500, borderLeft: `1px solid ${HEAD_LINE}`, paddingLeft: 10, marginLeft: 10 }}>Policy Impacts Visualiser</span>
          </p>
        </div>
        <div aria-hidden="true" style={{ height: 4, background: STRIPE }} />
      </header>

      {/* Gate card */}
      <main style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", padding: "40px 16px" }}>
        <div style={{ background: "#ffffff", border: `1px solid ${BORDER}`, borderRadius: 6, padding: "clamp(24px, 5vw, 40px) clamp(20px, 5vw, 44px)", maxWidth: 480, width: "100%", boxSizing: "border-box" }}>

          <p style={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: TEXT_MID, margin: "0 0 8px" }}>
            Preview access
          </p>
          <h1 style={{ fontSize: "clamp(22px, 3vw, 28px)", fontWeight: 650, color: INK, margin: "0 0 16px", letterSpacing: "-0.02em", lineHeight: 1.2, display: "inline-block", borderBottom: `3px solid ${CORAL}`, paddingBottom: 4 }}>
            This dashboard is a work in progress
          </h1>

          <div style={{ background: WARN_BG, border: "1px solid #fed7ca", borderLeft: `4px solid ${CORAL}`, borderRadius: 6, padding: "14px 18px", marginBottom: 22 }}>
            <p style={{ margin: 0, fontSize: 13.5, color: WARN_TEXT, lineHeight: 1.65 }}>
              The data currently shown is <strong>training data</strong>, manually split into Baseline and Scenario for development purposes. The results are <strong>not meaningful</strong> — this preview is for illustrative purposes only.
            </p>
          </div>

          <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <label htmlFor="passcode" style={{ fontSize: 14, color: TEXT_MID, lineHeight: 1.7 }}>
              Enter the preview passcode below to continue.
            </label>
            <input
              id="passcode"
              type="password"
              value={value}
              onChange={(e) => { setValue(e.target.value); if (error) setError(false); }}
              onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}
              placeholder="Passcode"
              autoFocus
              aria-invalid={error}
              aria-describedby={error ? "passcode-error" : undefined}
              style={{
                padding: "12px 14px", borderRadius: 6, fontSize: 15, color: TEXT_DARK, background: "#ffffff",
                border: `1.5px solid ${error ? ERROR : focused ? BLUE : "#7b8797"}`,
                boxShadow: focused ? `0 0 0 3px ${BLUE}40` : "none",
                outline: "none", boxSizing: "border-box", fontFamily: "inherit",
              }}
            />
            {error && (
              <p id="passcode-error" role="alert" style={{ margin: 0, fontSize: 13, color: ERROR, fontWeight: 600 }}>
                That passcode isn't right — try again.
              </p>
            )}
            <button
              type="submit"
              style={{
                marginTop: 6, padding: "10px 16px", borderRadius: 4, border: `1px solid ${CORAL}`, cursor: "pointer",
                background: CORAL, color: "#ffffff", fontWeight: 700, fontSize: 19, fontFamily: "inherit",
              }}
            >
              Enter Dashboard →
            </button>
          </form>
        </div>
      </main>
    </div>
  );
}

export default PasscodeGate;
